"""Complete synthetic 2x2 encoded images; runtime tests need only stdlib."""
import base64
import struct
import zlib


def png(width=2, height=2, pixels=None):
    def chunk(kind, body):
        return struct.pack(">I",len(body))+kind+body+struct.pack(">I",zlib.crc32(kind+body)&0xffffffff)
    if pixels is None: pixels=zlib.compress((b"\x00"+b"\x12\x34\x56"*width)*height)
    return (b"\x89PNG\r\n\x1a\n"+chunk(b"IHDR",struct.pack(">IIBBBBB",width,height,8,2,0,0,0))
            +chunk(b"IDAT",pixels)+chunk(b"IEND",b""))

PNG=png()

JPEG=base64.b64decode(
    ''
)

PROGRESSIVE_JPEG=base64.b64decode(
    ''
)

WEBP=base64.b64decode(
    'UklGRjQAAABXRUJQVlA4ICgAAACQAQCdASoCAAIAAUAmJYgCdLoAA5gA/vmo7+1Niqnnd+hRsol8wAAA'
)

